CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_library (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider VARCHAR(30) NOT NULL, external_manga_id BIGINT NOT NULL CHECK (external_manga_id > 0), title_snapshot VARCHAR(500) NOT NULL, cover_url_snapshot TEXT, reading_status VARCHAR(30) NOT NULL CHECK (reading_status IN ('READING','PLAN_TO_READ','COMPLETED','ON_HOLD','DROPPED')), added_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_user_manga UNIQUE (user_id, provider, external_manga_id));
CREATE INDEX ix_library_user_status ON user_library(user_id, reading_status);
CREATE TABLE reading_sources (id UUID PRIMARY KEY, provider VARCHAR(30) NOT NULL, external_manga_id BIGINT NOT NULL, source_name VARCHAR(150) NOT NULL, source_url TEXT NOT NULL CHECK (source_url LIKE 'https://%'), source_type VARCHAR(30) NOT NULL CHECK (source_type IN ('OFFICIAL_LINK','LICENSED_READER')), verification_status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING','VERIFIED','REJECTED')), license_reference TEXT, is_active BOOLEAN NOT NULL DEFAULT FALSE, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reading_progress (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider VARCHAR(30) NOT NULL, external_manga_id BIGINT NOT NULL CHECK (external_manga_id > 0), reading_source_id UUID REFERENCES reading_sources(id) ON DELETE SET NULL, chapter_external_id VARCHAR(255), chapter_label VARCHAR(100), page_index INTEGER CHECK (page_index IS NULL OR page_index >= 0), scroll_position NUMERIC CHECK (scroll_position IS NULL OR scroll_position >= 0), last_read_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_progress_user_manga UNIQUE(user_id,provider,external_manga_id));
